  ('acadia-maine', '12A', 'Acadia National Park', 'United States', 'Granite coast, carriage roads and Cadillac sunrise', 'future', 'verified', 'mountainValley', 'New England', '{"hiking","ocean","glamping","wildlife","family","parks"}', '{"coastal","rugged","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Cadillac Mountain summit and first sunrise","source":"https://www.nps.gov/acad/planyourvisit/cadillac-mountain.htm","accessed":"2026-10-02","si":["hiking","adventure","romance"],"booking_route":"none needed on foot; vehicles need the Cadillac Summit Road reservation","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"1,530 ft summit; from October 7 to March 6 the first place in the country to see the sun rise; reachable on foot by the North Ridge (4.4 mi round trip) or South Ridge (7.1 mi round trip) trails"},{"name":"Park Loop Road","source":"https://www.nps.gov/acad/planyourvisit/park-loop-road.htm","accessed":"2026-10-02","si":["family","senior","ocean"],"booking_route":"park entrance pass ($35 private vehicle, 7 days)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","move"],"draw_rank":2,"blurb":"the 27-mile scenic drive around the east side of Mount Desert Island, built 1921-1958, reaching Sieur de Monts, Sand Beach, Otter Point, Jordan Pond and Cadillac Mountain"},{"name":"The Rockefeller carriage roads","source":"https://www.nps.gov/acad/planyourvisit/cr_guide.htm","accessed":"2026-10-02","si":["family","hiking","senior"],"booking_route":"none needed beyond the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"45 miles of broken-stone carriage roads built 1913-1940, open to walkers, cyclists, riders and skiers; Class 1 e-bikes permitted, Class 2 and 3 prohibited"},{"name":"Jordan Pond and the Jordan Pond Loop","source":"https://www.nps.gov/acad/planyourvisit/hikes-jordan-pond.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed beyond the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"an inland lake bound by Penobscot and Pemetic mountains and The Bubbles, with day hikes from level to strenuous starting at the boat launch, carriage road sign 15 or The Bubbles lot"},{"name":"Thunder Hole and Ocean Path","source":"https://home.nps.gov/places/thunder-hole.htm","accessed":"2026-10-02","si":["ocean","hiking","family"],"booking_route":"none needed beyond the park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"a narrow inlet where wave spray can top 40 feet, best one to two hours before high tide, on the 2.2-mile Ocean Path from Sand Beach toward Otter Point"},{"name":"Cadillac Summit Road vehicle reservation","source":"https://www.nps.gov/acad/planyourvisit/vehicle_reservations.htm","accessed":"2026-10-03","si":["adventure","hiking","family"],"booking_route":"Recreation.gov only - \"not available for purchase at the park\"","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"required Wed May 20 through Sun Oct 25, 2026, $6, \"sold online in advance at Recreation.gov\"; 30 percent released 90 days ahead, 70 percent at 10 am ET two days ahead; not required on foot, bike or by taxi"},{"name":"Jordan Pond House popovers","source":"https://jordanpondhouse.com/","accessed":"2026-10-02","si":["culture","culinary","family"],"booking_route":"walk-in for most tables","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":7,"blurb":"tea and popovers on the lawn since 1893, operated by Dawnland LLC; most tables are held for walk-ins and the