insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('hammonasset-beach-connecticut', '12A', 'Hammonasset Beach State Park', 'United States', 'Connecticut''s largest shoreline park and its clam shacks', 'future', 'verified', 'mountainValley', 'New England', '{"family","culinary","hiking","senior","wildlife","parks"}', '{"coastal","family-friendly","serene"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Hammonasset Beach (two-mile swimming beach)","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - free for Connecticut-registered vehicles; out-of-state parking paid at the gate","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"a two-mile sandy stretch of beach\" on Long Island Sound at \"Connecticut''s largest shoreline park\"; \"Cool off with a dip in the refreshing saltwater or don your scuba gear and explore what''s below anywhere along the park''s two-mile stretch of shoreline\"; open daily 8:00 a.m. to sunset"},{"name":"Hammonasset Beach State Park Campground","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["family","group","senior"],"booking_route":"ReserveAmerica (connecticutstateparks.reserveamerica.com), opens 11 months ahead; or 1-877-668-CAMP (2267)","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":2,"blurb":"\"558 grassy open campsites (including eight rustic cabins)\"; water and electric $35 resident / $45 non-resident, basic $20 / $30, rustic cabin $70 / $80 with a 7-night Sunday-to-Sunday minimum, plus a $9 processing fee; bathhouses with hot showers, camp store, playground, amphitheater; \"Pets are not allowed at this campground\" in season"},{"name":"Meigs Point Nature Center","source":"http://www.meigspointnaturecenter.org/","accessed":"2026-10-03","si":["family","wildlife","senior"],"booking_route":"walk-in, free; group programmes and birthday parties by phone 203-245-8743","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"a state-of-the-art environmental education center\" with \"4,000 square feet of hands-on learning experiences, including a saltwater touch tank; live turtles, snakes, amphibians, crabs, and fish\"; \"Nature Center Admission: Free\"; Tuesday-Sunday 10am-5pm April-October, 10am-4pm November-March"},{"name":"Hammonasset Beach State Park Walk and the boardwalk","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"3.4-mile paved multi-use trail... Level of difficulty: Easy... This heavily trafficked out-and-back trail hugs the coastline, offering shoreline vistas from the nature center all the way to the western section of the beach\""},{"name":"Surfcasting from the Meigs Point and West Beach jetties","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["sports","adventure"],"booking_route":"none needed - Connecticut fishing licence rules apply (portal.ct.gov/DEEP/Fishing/CT-Fishing)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Surf cast from the stone breakwater. Cast a line from the serenity of your canoe. Catch dinner while catching the sunrise.\" Daytime fishing at Meigs Point Jetty and West Beach Jetty (May-October); night fishing along the entire beach in peak season only; blackfish, striped bass and fluke"},{"name":"Willard''s Island Nature Trail","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["hiking","wildlife","senior"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"1.1-mile paved trail... Level of difficulty: Easy... Head inland and away from the beach for some solitude and a closer look at the park''s expansive salt marshes.\""},{"name":"Meigs Point Trail","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"1.4-mile trail... Level of difficulty: Easy... This out-and-back trail takes along the rocky, sandy shoreline takes you out and around Meigs Point.\""},{"name":"The BURT bike trail","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["family","sports"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Ride through the park on Hammonasset''s three-mile BURT trail from West Beach all the way to Meigs Point.\""},{"name":"Meigs Point jetty kayak and boat launch","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["adventure","sports"],"booking_route":"none needed - park launch","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Follow signs to Meigs Point and the fishermen''s parking area. Look for the launch on the east side of the Meigs Point jetty.\" Life jackets are mandatory October 1 through May 31, and children under 12 must wear them year-round"},{"name":"Hammonasset picnic shelters","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["group","family"],"booking_route":"ReserveAmerica (Hammonasset Picnic Shelter, connecticutstateparks.reserveamerica.com)","commission_status":"none","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"\"Rent one of our four picnic shelters: (3) 20 x 60-ft., (1) 20 x 33-ft. Each shelter has space for 65 people, 12 picnic tables and 2 charcoal pedestal grills.\" Rental fee $220 plus $9 processing fee"},{"name":"Meigs Point events: Beach Cleanup (Oct 3, 2026) and Astronomy Night (Nov 6, 2026)","source":"http://www.meigspointnaturecenter.org/","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"not observed - contact 203-245-8743 or rangermpnc@gmail.com","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":22,"blurb":"the nature center lists a Beach Cleanup \"Saturday, October 3rd 10am - 12pm\" and an Astronomy Night \"Friday, November 6th\", alongside \"40 educational programs\" for groups"},{"name":"Lenny & Joe''s Fish Tale Restaurant, Madison","source":"https://ctvisit.com/listings/lenny-joes-fish-tale-restaurant-madison","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone (203) 245-7289 (own site ljfishtale.com returned 403 this session)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":6,"blurb":"\"Started as a ''roadside clam stand'' in 1979 and today continues the tradition of serving the highest quality seafood available to diners who come from all over New England\"; seafood \"broiled, baked, fried, sauteed, charbroiled, steamed\" at 1301 Boston Post Rd., Madison; Sunday-Thursday 11:30 a.m.-8:30 p.m., Friday and Saturday to 9 p.m.; a second location in Westbrook"},{"name":"The Place Restaurant, Guilford","source":"https://www.theplaceguilford.com/","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"not observed - no reservation policy on own site; phone 203-453-9276","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":8,"blurb":"\"a truly unusual outdoor seafood restaurant in Guilford, CT where visitors dine outdoors while a crackling wood fire roasts savory clams, smoky lobsters, sweet corn and much more\"; tree-stump seats at red tables; 901 Boston Post Rd; open May through late October, weather permitting; cash and ATM, no credit cards"},{"name":"Guilford Lobster Pound","source":"https://www.guilfordlobsterpound.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-up; phone (203) 453-6122","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":10,"blurb":"\"Hot, buttery lobster rolls served dockside.\" Bart Mansi has run it since 1991, catching lobster from his 42-foot boat; Hot Buttered Lobster Roll $27 with 4 oz of meat; 505A Whitfield St., Guilford; Monday-Thursday 12-6pm, Friday-Sunday 12-7pm, weather dependent; BYOB, cash only"},{"name":"Lobster Landing, Clinton","source":"https://www.lobsterlandingct.com/","accessed":"2026-10-03","si":["culinary","senior"],"booking_route":"online ordering on own site; phone 860.669.2005","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":11,"blurb":"waterfront lobster shack at 152 Commerce St, Clinton, claiming \"The Best Lobster Roll in New England\"; lobster rolls at market rate from $31.50; open daily from 11AM; BYOB; a Senior Menu every Wednesday for age 60+"},{"name":"Chamard Vineyards, Clinton","source":"https://www.chamard.com/","accessed":"2026-10-03","si":["wine","culinary","romance"],"booking_route":"OpenTable, or phone (860) 664-0299","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":13,"blurb":"farm, winery and bistro at 115 Cow Hill Road, Clinton, with \"acclaimed cuisine, thoughtfully paired with our wines\"; wine tastings; Wednesday-Saturday 12-9pm, Sunday 11am-5pm; a sister waterfront cafe, Pas Place, serves Chamard wines"},{"name":"Bishop''s Orchards, Guilford","source":"https://www.bishopsorchards.com/","accessed":"2026-10-03","si":["family","culinary","wine"],"booking_route":"walk-in; pick-your-own pricing and availability by phone 203-458-PICK","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","eat","activities"],"draw_rank":15,"blurb":"\"A 150+ year local tradition rooted in fresh, local food & memorable experiences\"; year-round farm market at 1355 Boston Post Road, pick-your-own (berries and peaches in summer, apples and pears in fall), \"Bishop''s fruit wines and hard ciders\" with daily tastings, a creamery 11am-9pm, and a Fall Festival open through 11/1"},{"name":"Madison Beach Hotel, Curio Collection by Hilton","source":"https://ctvisit.com/node/26366","accessed":"2026-10-03","si":["romance","wellness","culinary"],"booking_route":"Hilton booking (madisonbeachhotel.curiocollection.com) or (203) 245-1404","commission_status":"unknown","commission":"hotel","tier":"luxury","price_band":"luxury","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay","eat","beauty"],"draw_rank":16,"blurb":"\"Indulge in AAA Four Diamond elegance at Connecticut''s premier luxury beachfront resort\" at 94 W. Wharf Rd., Madison; \"33 of the 34 guest rooms feature furnished balconies overlooking the Long Island Sound\"; joined Hilton''s Curio Collection in 2015"},{"name":"Water''s Edge Resort and Spa, Westbrook","source":"https://www.watersedgeresortandspa.com/","accessed":"2026-10-03","si":["wellness","family","romance"],"booking_route":"own website booking; Reservations 800.222.5901","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","beauty"],"draw_rank":17,"blurb":"\"Connecticut''s Largest Beachfront Resort\" at 1525 Boston Post Road, Westbrook, with \"a private white sand beach, restaurants, entertainment, a premium spa\"; ocean-view rooms, suites, villas by the sea and weekly house rentals; Dattilo, Seaview Bistro, Sunset Bar & Grill, Julia''s Beach Bar and Cappuccio Caffe"},{"name":"Riverdale Farm Campsites, Clinton","source":"https://riverdalefarmcampsites.com/","accessed":"2026-10-03","si":["family","motoring","glamping"],"booking_route":"phone/email only ((860) 669-5388, riverdalefarmcampsite@comcast.net)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"Part of a 100-acre colonial farm, Riverdale Farm Campsites is nestled between a winding country road and the meandering Hammonasset River\"; wooded, waterfront and meadow sites, full hookups and 50-amp service, cabins, a pool (new in 2025), spring-fed pond swimming; 111 River Road, Clinton"},{"name":"Hartwoods, North Guilford (Hipcamp)","source":"https://www.hipcamp.com/en-US/discover/connecticut/hammonasset-beach","accessed":"2026-10-03","si":["family","motoring","hiking"],"booking_route":"Hipcamp online booking","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"a one-site wooded tent and RV pitch with 30-amp electricity and water hookup, listed by Hipcamp as 9.7 mi from Hammonasset Beach and rated 97% from 102 reviews; re-typed 2026-10-03 from glamping to campground - the Hipcamp listing reads ''Tent, RV''"},{"name":"Shoreline cottages near Hammonasset (Airbnb)","source":"https://www.airbnb.com/hammonasset-beach-state-park-madison-ct/stays","accessed":"2026-10-03","si":["family","romance"],"booking_route":"Airbnb online booking","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"Airbnb''s Hammonasset page lists shoreline rentals in Madison, Guilford, Westbrook and Clinton, among them a Madison carriage house \"Just 1 mile and your feet are on 2 miles of white sandy beach\" and a Clinton cottage a \"stone''s throw from Hammonasset State Park\""},{"name":"Indian River Marina & Kayak, Clinton","source":"https://www.indrivmar.com/","accessed":"2026-10-03","si":["adventure","family","wildlife"],"booking_route":"own website reservations; Docklyne online booking; phone (860) 664-3704","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":20,"blurb":"\"about one-quarter mile up the Indian River from the Clinton Harbor where three rivers – the Hammonasset, Indian, and Hammock – converge on their way to Long Island Sound\"; kayak, canoe and paddleboard rentals launching on the Indian River, with delivery and drop-offs to nearby waters; 58 Commerce Street, Clinton"},{"name":"Thimble Islands Cruise (Sea Mist), Stony Creek, Branford","source":"https://www.thimbleislandcruise.com/","accessed":"2026-10-03","si":["sailing","family","senior"],"booking_route":"FareHarbor (''Book Online Now''); phone 203-488-8905","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"Sea Mist, a 44-foot boat, runs a \"45 minute narrated cruise\" from the Stony Creek Dock through the Thimble Islands; the 40-foot catamaran Island Time runs a one-hour Branford River and shoreline cruise"},{"name":"Guilford Town Green","source":"https://ctvisit.com/listings/town-guilford","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"none needed - public town green","commission_status":"none","tier_absent_reason":"not-sold","wells":["shop","activities"],"draw_rank":23,"blurb":"the Connecticut Office of Tourism: \"Guilford, settled in 1639, is a charming town steeped in history and brimming with modern attractions. Known for its award-winning Town Green, it offers unique shopping, dining, galleries, and family-friendly events.\""},{"name":"Downtown Madison and R.J. Julia Booksellers","source":"https://ctvisit.com/articles/coastal-central-connecticut","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"none needed - public downtown; shops walk-in","commission_status":"none","tier_absent_reason":"not-sold","wells":["shop"],"draw_rank":25,"blurb":"Madison''s \"pedestrian-friendly downtown\" with bookstores, galleries, cinema, tea emporiums, cafes and boutiques; the state tourism office calls R.J. Julia Booksellers \"famous independently and woman-owned\""},{"name":"Ashley''s Ice Cream","source":"https://ctvisit.com/articles/coastal-central-connecticut","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (own site ashleysicecream.com did not load this session)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"the Connecticut Office of Tourism names \"Ashley''s Ice Cream for fresh ice cream consistently voted some of the best in the state\" among the coastal towns'' stops"},{"name":"Aces High RV Park, East Lyme","source":"https://www.aceshighrvpark.com/","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"Camping.com booking portal linked from the park''s site, or phone 860-739-8858","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"Luxury RV accommodations designed for RV enthusiasts who appreciate quality and comfort with luxury amenities\"; a heated saltwater pool, freshwater pond, hiking trails and a pickleball court; open year-round; 301 Chesterfield Road, East Lyme"},{"name":"Odetah Camping Resort, Bozrah","source":"https://www.odetah.com/","accessed":"2026-10-03","si":["family","motoring","glamping"],"booking_route":"own website booking (odetah.com/book-online/) or 800.448.1193","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"the Connecticut Office of Tourism lists Odetah as \"Offering lake boating and fishing and camping options from full RV hookups to yurts\"; its own site: \"Odetah''s mission is to deliver the WOW in camping!\", with two-bedroom Deluxe Cabins sleeping up to 6, a Safari area of 14 sites with water, electric and graywater hookups, and primitive tent sites; 38 Bozrah Street Ext, Bozrah"},{"name":"Water Forest Retreat - Octagon (Hipcamp)","source":"https://www.hipcamp.com/en-US/discover/connecticut/hammonasset-beach","accessed":"2026-10-03","si":["glamping","romance","wellness"],"booking_route":"Hipcamp online booking","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"an octagon glamping stay listed by Hipcamp at 28 mi from Hammonasset Beach, rated 100% from 37 reviews; the Connecticut Office of Tourism also names \"Water Forest Retreat - Octagon\" among the state''s glamping and unique stays (ctvisit.com/articles/great-camping-destinations, read 2026-10-03)"},{"name":"Hotel Marcel New Haven, Tapestry Collection by Hilton","source":"https://www.hilton.com/en/locations/usa/connecticut/guilford/","accessed":"2026-10-03","si":["culture","romance","senior"],"booking_route":"hilton.com (brand booking) or hotelmarcel.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay","eat"],"draw_rank":31,"blurb":"Hilton lists it as \"Hotel Marcel New Haven, Tapestry Collection by Hilton\", 12.39 miles from Guilford; its own site: \"Reimagined Pirelli building designed by modernist architect Marcel Breuer\", on the National Register of Historic Places, all-electric with 1,000+ photovoltaic panels, restaurant and bar BLDG (hotelmarcel.com, read 2026-10-03)"},{"name":"Spark by Hilton Guilford","source":"https://www.hilton.com/en/locations/usa/connecticut/guilford/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":32,"blurb":"Hilton''s Guilford locations page lists \"Spark by Hilton Guilford\" at 1.31 miles from Guilford - the closest Hilton-family hotel to Guilford on that page; nothing else about the property is stated here"},{"name":"Graduate by Hilton New Haven","source":"https://www.hilton.com/en/locations/usa/connecticut/guilford/","accessed":"2026-10-03","si":["culture","family"],"booking_route":"hilton.com (brand booking)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":33,"blurb":"Hilton''s Guilford locations page lists \"Graduate by Hilton New Haven\" at 13.16 miles from Guilford; nothing else about the property is stated here"},{"name":"Life jackets and paddling kit for Hammonasset","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["adventure","family","ocean"],"booking_route":"affiliate link to the retailer (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":34,"blurb":"CT State Parks: \"Bring your canoe or kayak and enjoy a paddle while soaking in the sun and views of the Connecticut shoreline.\" KNOW BEFORE YOU GO: \"Life jackets are mandatory from October 1 – May 31. Children under 12 must wear a life jacket year-round.\""},{"name":"Raised firepit for a Hammonasset campsite","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["family","group"],"booking_route":"affiliate link to the retailer (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":9.25,"commission_pct_high":9.25,"commission_basis":"published","wells":["gear"],"draw_rank":35,"blurb":"CT State Parks, campground: \"Campers are welcome to bring their own raised firepit or rent one from the campground store (depending on availability).\" \"Firewood and ice available on site\"; \"Recycling stations for mini propane cylinders\"."},{"name":"Surf-casting kit for the Meigs Point and West Beach jetties","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03","si":["sports","ocean"],"booking_route":"affiliate link to the retailer (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["gear"],"draw_rank":36,"blurb":"CT State Parks: \"Surf cast from the stone breakwater.\" \"Find all your favorite ways to go saltwater fishing here from spring to fall.\" The page links \"Saltwater Fishing in Connecticut''s State Parks - Licenses and permits, current regulations, and more\"."}],"faq":[{"q":"How much does it cost to get into Hammonasset Beach?","a":"Connecticut residents park free. Out-of-state vehicles pay $22 on weekends and holidays, $15 on weekdays and $7 after 4:00 pm; an out-of-state season pass is $112.","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"},{"q":"What are Hammonasset Beach State Park''s hours?","a":"Open daily 8:00 a.m. to sunset, and open 24 hours for camping and fishing from Memorial Day to Columbus Day. The 2026 season runs May 22 to October 12 (noon).","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"},{"q":"How much is camping at Hammonasset Beach State Park?","a":"Water and electric sites are $35 for residents and $45 for non-residents; basic sites $20 and $30; rustic cabins $70 and $80 with a 7-night Sunday-to-Sunday minimum. A $9 processing fee applies. Book on ReserveAmerica or at 1-877-668-CAMP (2267).","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"},{"q":"What time is check-in at Hammonasset Beach State Park?","a":"\"Check in time for campsites is 1:00 p.m. to 10:00 p.m.\" Arrivals after 10 p.m. use a temporary stopover area until morning. Cabins check in from 2:00 p.m. on Sundays and check out at 11:00 a.m. on departure day.","source":"https://connecticutstateparks.reserveamerica.com/camping/hammonasset-beach-state-park/r/campgroundDetails.do?contractCode=CT&parkId=100101","accessed":"2026-10-03"},{"q":"Can you bring dogs to Hammonasset Beach State Park?","a":"On a leash in the picnic areas year-round, and on the beach only from September 30 to April 1. The campground does not allow pets in season.","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"},{"q":"Can you drink alcohol at Hammonasset Beach State Park?","a":"Not on the beach or boardwalk. Connecticut State Parks: \"Alcoholic beverages are permitted in many state parks and forests, but not on beaches or boardwalks.\"","source":"https://ctparks.com/park-policies","accessed":"2026-10-03"},{"q":"Can you swim at Hammonasset Beach State Park?","a":"Yes, anywhere along the two-mile shoreline. State parks say \"Lifeguards are staffed at some of these areas during the peak summer season. Lifeguard coverage on any specific day is dependent on seasonality, time of day, and staffing levels.\" Beach rules include no alcohol, glass, pets, flotation devices or snorkels in swimming areas.","source":"https://ctparks.com/swimming","accessed":"2026-10-03"},{"q":"What is the water quality at Hammonasset Beach State Park?","a":"Connecticut State Parks publishes a Swimming Areas Water Quality Report, \"updated weekly from Memorial Day through Labor Day\", at ctparks.com/water-quality-report.","source":"https://ctparks.com/swimming","accessed":"2026-10-03"},{"q":"Can you fish at Hammonasset Beach State Park?","a":"Yes. Daytime fishing is allowed at the Meigs Point and West Beach jetties (May-October), and night fishing along the entire beach in peak season only. The park names surf casting for blackfish, striped bass and fluke.","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"},{"q":"What town is Hammonasset Beach State Park in?","a":"Madison, Connecticut - 1288 Boston Post Rd., Madison, CT 06443.","source":"https://ctparks.com/parks/hammonasset-beach-state-park","accessed":"2026-10-03"}],"seo":{"meta_title":"Hammonasset Beach State Park: Beach, Camping & Shoreline Seafood | TravelWell","meta_description":"Connecticut''s largest shoreline park: a two-mile beach, 558-site campground, gate fees, dog and beach rules, and the Madison-Guilford clam shacks nearby.","slug":"hammonasset-beach-state-park-connecticut","primary_keyword":"Hammonasset Beach State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Hammonasset Beach State Park"}}'::jsonb, 35),
